`timescale 1ns/1ps
module Dut(input logic [7:0] a, output logic [63:0] y);
  always_comb y = a + $time;
endmodule
module Top;
  logic [7:0] a;
  logic [63:0] y;
  Dut dut(.a(a), .y(y));
  initial begin
    a = 0;
    #3 $display("time=%0d y=%0d", $time, y);
    a = 2;
    #0 $display("time=%0d y=%0d", $time, y);
    $finish;
  end
endmodule

`timescale 1ns/1ps
module Dut(input logic [7:0] a, output logic [63:0] y);
  always_comb y = a + $time;
endmodule
module Top;
  timeunit 1ps; timeprecision 1ps;
  logic [7:0] a;
  bit progress = 0;
  clocking settled @(progress);
    input #0 seen = progress;
  endclocking
  Dut dut(.a(a), .y());
  initial begin
    a = 0;
    progress <= ~progress; @(settled);
    #3000;
    progress <= ~progress; @(settled);
    $display("time=%0t y=%0d", $time, dut.y);
    $finish;
  end
endmodule
